package com.trush.game.world;

import com.trush.game.objects.Prop;

/**
 * A story stage (a floor's look and feel): its name, music, room themes (tilesets generated by
 * tools/gen_sprites.py), how layout letters map to furniture, and the door barricade style.
 * Floor 1 is the village, floor 2 the town, floor 3 the city (at night); floors past the last stage
 * replay it, tougher.
 */
public enum Stage {
    VILLAGE("THE VILLAGE", "village", "boss_village", "yard", "chapel", "square",
            new String[]{"cottage", "yard", "barn", "orchard", "square"},
            "The village is safe... for now.", Barricade.PLANKS, 0f, false),
    TOWN("THE TOWN", "town", "boss_town", "street", "shop", "townhall",
            new String[]{"street", "market", "alley", "park"},
            "The town is quiet... for now.", Barricade.ROAD, 0.45f, false),
    CITY("THE CITY", "city", "boss_city", "avenue", "pawnshop", "helipad",
            new String[]{"avenue", "subway", "rooftop", "construction"},
            "The city sleeps... for now.", Barricade.TAPE, 0.3f, true);

    /** What's drawn across the doors of a locked room. */
    public enum Barricade { PLANKS, ROAD, TAPE }

    public final String title;
    /** Track in assets/music/ (without .ogg). */
    public final String music;
    /** Track for this stage's boss fights ("Harvest of Fear", "Rush Hour Rampage"...). */
    public final String bossMusic;
    public final String startTheme;
    public final String treasureTheme;
    public final String bossTheme;
    public final String[] combatThemes;
    /** Line on the floor-clear screen. */
    public final String clearText;
    public final Barricade barricade;
    /** Chance that a combat room has open sewer hatches (pits) in its floor. */
    public final float pitChance;
    /** Night: a darkness vignette around the player, lamps cast light (GameWorld.drawNight). */
    public final boolean night;

    Stage(String title, String music, String bossMusic, String startTheme, String treasureTheme, String bossTheme,
          String[] combatThemes, String clearText, Barricade barricade, float pitChance, boolean night) {
        this.title = title;
        this.music = music;
        this.bossMusic = bossMusic;
        this.startTheme = startTheme;
        this.treasureTheme = treasureTheme;
        this.bossTheme = bossTheme;
        this.combatThemes = combatThemes;
        this.clearText = clearText;
        this.barricade = barricade;
        this.pitChance = pitChance;
        this.night = night;
    }

    /** The stage of a story floor (1-based); floors beyond the last stage stay on it. */
    public static Stage forFloor(int floor) {
        Stage[] all = values();
        return all[Math.max(0, Math.min(floor, all.length) - 1)];
    }

    /** Furniture for a layout letter (see RoomTemplates): the town has benches and lamps, the city parked cars and lamps. */
    public Prop.Kind propFor(char c) {
        switch (c) {
            case 'T':
                return Prop.Kind.TABLE;
            case 'H':
                return this == TOWN ? Prop.Kind.BENCH : this == CITY ? Prop.Kind.CAR : Prop.Kind.HAY;
            case 'B':
                return Prop.Kind.BARREL;
            case 'C':
                return Prop.Kind.CRATE;
            case 'K': // a parked car on any stage (the Traffic Light's arena)
                return Prop.Kind.CAR;
            case 'P':
                return this == VILLAGE ? Prop.Kind.PILLAR : Prop.Kind.LAMP;
            default:
                return null;
        }
    }
}
